from collections import defaultdict


class Graph:
    def __init__(self, directed=False):
        self.adj = defaultdict(list)
        self.directed = directed

    def add_edge(self, u, v):
        self.adj[u].append(v)
        if not self.directed:
            self.adj[v].append(u)

    def dfs(self, start, target=None):
        """DFS from start. Returns visited set, or True/False if target given."""
        if start not in self.adj and target is not None and start != target:
            return False

        visited = set()
        stack = [start]

        while stack:
            node = stack.pop()
            if node in visited:
                continue
            visited.add(node)
            if target is not None and node == target:
                return True
            for neighbor in reversed(self.adj[node]):
                if neighbor not in visited:
                    stack.append(neighbor)

        return False if target is not None else visited

    def dfs_recursive(self, start, target=None):
        """Recursive DFS. Returns visited set, or True/False if target given."""
        visited = set()

        def _dfs(node):
            visited.add(node)
            if target is not None and node == target:
                return True
            for neighbor in self.adj[node]:
                if neighbor not in visited:
                    if _dfs(neighbor):
                        return True
            return False

        result = _dfs(start)
        return result if target is not None else visited

    def dfs_all(self):
        """DFS over all components. Returns list of connected component sets."""
        visited = set()
        components = []
        for node in list(self.adj):
            if node not in visited:
                component = set()
                stack = [node]
                while stack:
                    curr = stack.pop()
                    if curr in visited:
                        continue
                    visited.add(curr)
                    component.add(curr)
                    for neighbor in self.adj[curr]:
                        if neighbor not in visited:
                            stack.append(neighbor)
                components.append(component)
        return components


if __name__ == "__main__":
    g = Graph()
    g.add_edge(0, 1)
    g.add_edge(0, 2)
    g.add_edge(1, 3)
    g.add_edge(1, 4)
    g.add_edge(2, 5)
    g.add_edge(5, 6)

    print("DFS from 0:", g.dfs(0))
    print("Path 0->6 exists:", g.dfs(0, target=6))
    print("Path 0->9 exists:", g.dfs(0, target=9))
    print("Components:", g.dfs_all())

    # Disconnected graph
    g2 = Graph()
    g2.add_edge("a", "b")
    g2.add_edge("c", "d")
    print("Components:", g2.dfs_all())
